60	/** Loads the default startup player (LeBron James) when present in dim_player. */
61	export async function loadDefaultPlayer(): Promise<PlayerSuggestion | null> {
62	  const rows = await query<PlayerSuggestion>(`
63	    SELECT player_id, full_name, from_year, to_year, is_active
64	    FROM dim_player
65	    WHERE full_name = 'LeBron James'
66	    LIMIT 1
