72	export async function searchPlayerSuggestions(q: string): Promise<PlayerSuggestion[]> {
73	  return query<PlayerSuggestion>(
74	    `
75	    SELECT player_id, full_name, from_year, to_year, is_active
76	    FROM dim_player
77	    WHERE lower(full_name) LIKE lower($1)
78	    ORDER BY to_year DESC, full_name ASC
