98	    `
99	    SELECT
100	      type AS award,
101	      season_end_year AS season_year,
102	      1 AS count
103	    FROM v_player_honors_full
104	    WHERE CAST(person_id AS VARCHAR) = $1
105	      AND is_winner = true
106	    ORDER BY season_end_year DESC, type ASC
107	  `,
