134	 * When `NBA_HONORS_DUCKDB_PATH` points at a basketball-data DuckDB file, winners are read
135	 * from `v_player_honors_full` (accurate MVP counts). Otherwise uses `fact_player_awards`
136	 * on the primary database from `NBA_DUCKDB_PATH` / `data/nba.duckdb`.
137	 */
138	export async function loadPlayerAwards(playerId: string): Promise<PlayerAwardRow[]> {
139	  if (isHonorsDbConfigured()) {
140	    try {
141	      const honorsRows = await loadPlayerAwardsFromHonorsDb(playerId);
142	      if (honorsRows.length > 0) {
143	        return honorsRows;
144	      }
145	    } catch {
146	      // Fall back to primary schema if honors view is missing or incompatible.
147	    }
148	  }
149	
150	  return loadPlayerAwardsFromPrimaryDb(playerId);
151	}
152	
153	/**
154	 * Loads career season-by-season statistics for a player.
155	 *
156	 * Returns one row per (season_year, is_playoffs) combination, ordered
157	 * newest-first with playoff rows before regular-season rows.
158	 */
159	export async function loadCareerStats(playerId: string): Promise<CareerStatRow[]> {
160	  const rows = await query<CareerStatRow>(
161	    `
162	    SELECT
163	      season_year,
164	      is_playoffs,
165	      gp,
166	      gs,
167	      min,
168	      pts,
169	      ast,
170	      reb,
171	      stl,
172	      blk,
173	      ts_pct,
174	      per,
175	      bpm,
176	      vorp
177	    FROM fact_player_season_stats
178	    WHERE player_id = $1
179	    ORDER BY season_year DESC, is_playoffs DESC
180	  `,
181	    [playerId],
182	  );
183	  return dedupeCareerStats(rows);
184	}
