190	  const rows = await query<TeamRow>(
191	    `
192	    SELECT team_id, team_abbrev, team_name
193	    FROM dim_team
194	    WHERE lower(team_abbrev) = lower($1)
195	       OR lower(team_name) = lower($1)
196	       OR lower(team_name) LIKE lower($2)
197	    ORDER BY season_active_till DESC
198	    LIMIT 1
199	  `,
200	    [queryStr, `%${queryStr}%`],
201	  );
202	  return rows[0] || null;
203	}
